#!/usr/bin/env python3
from pathlib import Path
import pandas as pd,numpy as np,json,hashlib
ROOT=Path('/home/ubuntu/CHAOS'); OUT=ROOT/'experiments/multi_domain_native_edges_v1/imf_imts_export_to_gdp_v1'; OUT.mkdir(parents=True,exist_ok=True)
TRADE=ROOT/'experiments/multi_domain_native_adapters_v1/imf_imts_v1/IMF_IMTS_OBSERVED_RECORDS_2000_2024.csv'; MACRO=ROOT/'catalog_first/readiness_gate/macro_plus_eia_energy/MACRO_PLUS_EIA_ENERGY_COMPLETE_139_NUMERIC_RAW_2000_2024_WIDE.csv'; CONTRACT=ROOT/'experimental_contracts/IMF_IMTS_EXPORT_CONTRACTION_TO_GDP_CONTRACT_V1.json'; rng=np.random.default_rng(20260827); H=[1,2,3]
def main():
 t=pd.read_csv(TRADE); t=t[(t.indicator=='XG_FOB_USD')&(t.counterpart_country=='G001')&(t.frequency=='A')].copy(); t['year']=pd.to_numeric(t.time_period,errors='coerce').astype('Int64'); t['value']=pd.to_numeric(t.obs_value_raw,errors='coerce'); t=t.dropna(subset=['year','value']); t=t[['country','year','value']].rename(columns={'country':'entity_code','value':'exports_world_raw'}); t=t.sort_values(['entity_code','year']); t['export_contraction']=(t.groupby('entity_code').exports_world_raw.diff()<0); m=pd.read_csv(MACRO,usecols=['entity_code','year','wdi__NY.GDP.MKTP.KD.ZG']); m['year']=pd.to_numeric(m.year,errors='coerce').astype('Int64'); m['gdp_growth']=pd.to_numeric(m['wdi__NY.GDP.MKTP.KD.ZG'],errors='coerce'); rows=[]
 for e,g in t.groupby('entity_code'):
  g=g.merge(m[m.entity_code==e],on=['entity_code','year'],how='left').sort_values('year');
  for h in H:
   g[f'target_h{h}']=g['gdp_growth'].shift(-h); valid_target=g[f'target_h{h}'].notna()&g['gdp_growth'].notna(); g[f'outcome_h{h}']=pd.Series(np.where(valid_target,(g[f'target_h{h}']<=g['gdp_growth']-2.0).astype(float),np.nan),index=g.index)
  g['origin_valid']=g.year.between(2001,2021)&g.exports_world_raw.notna()&g.gdp_growth.notna(); rows.append(g[g.origin_valid][['entity_code','year','exports_world_raw','export_contraction','gdp_growth']+[f'outcome_h{h}' for h in H]])
 d=pd.concat(rows,ignore_index=True); metrics=[]; splits={'fit':(2001,2013),'validation':(2014,2018),'confirmation':(2019,2021)}
 def stat(x,y):
  x=np.asarray(x,dtype=bool); y=np.asarray(y,dtype=bool); a=y[x].mean() if x.sum() else np.nan; b=y[~x].mean() if (~x).sum() else np.nan; return float(a-b) if np.isfinite(a) and np.isfinite(b) else np.nan
 for split,(lo,hi) in splits.items():
  z=d[d.year.between(lo,hi)]
  for h in H:
   valid=z[f'outcome_h{h}'].notna(); zz=z[valid]; y=zz[f'outcome_h{h}'].astype(bool); x=zz.export_contraction.fillna(False).astype(bool); metrics.append({'split':split,'horizon':h,'rows':len(zz),'entities':int(zz.entity_code.nunique()),'contraction_positive':int(x.sum()),'outcome_positive':int(y.sum()),'risk_diff':stat(x,y),'event_rate':float(y.mean()) if len(y) else None})
 cm=pd.DataFrame([x for x in metrics if x['split']=='confirmation']); observed=float(cm.risk_diff.max()) if cm.risk_diff.notna().any() else np.nan; null=[]
 c=d[d.year.between(2019,2021)].copy(); valid_by_h={h:c[c[f'outcome_h{h}'].notna()].copy() for h in H}
 for _ in range(10000):
  vals=[]
  for h in H:
   z=valid_by_h[h]; ys=[]
   for e,g in z.groupby('entity_code'):
    a=g[f'outcome_h{h}'].astype(bool).to_numpy().copy(); rng.shuffle(a); ys.extend(zip(g.export_contraction.fillna(False).astype(bool).to_numpy(),a))
   if ys: vals.append(stat([q[0] for q in ys],[q[1] for q in ys]))
  null.append(np.nanmax(vals) if vals else np.nan)
 null=np.asarray(null); p=float((1+np.sum(null>=observed))/(len(null)+1)) if np.isfinite(observed) else None; val=next((x['risk_diff'] for x in metrics if x['split']=='validation' and x['horizon']==int(cm.loc[cm.risk_diff.idxmax(),'horizon'])) if cm.risk_diff.notna().any() else None,None)
 metrics_df=pd.DataFrame(metrics); metrics_df.to_csv(OUT/'IMF_IMTS_EXPORT_TO_GDP_METRICS_V1.csv',index=False); summ={'test_id':'IMF_IMTS_EXPORT_CONTRACTION_TO_GDP_V1','rows_origins':int(len(d)),'entities':int(d.entity_code.nunique()),'years':sorted(d.year.astype(int).unique().tolist()),'metrics':metrics,'observed_confirmation_max_risk_difference':observed,'null_method':'within-reporter permutation of target outcome labels with fixed raw export contraction exposure','null_replicates':10000,'null_mean':float(np.nanmean(null)),'null_sd':float(np.nanstd(null,ddof=1)),'null_q95':float(np.nanquantile(null,.95)),'p_value':p,'validation_at_selected_horizon':val,'minimum_coverage_pass':bool(all(x['contraction_positive']>=5 and x['outcome_positive']>=5 for x in metrics if x['split']=='confirmation')),'interpretation':'trade-to-GDP edge is research-only; no causal claim; no promotion unless confirmation and null rules pass'}; (OUT/'IMF_IMTS_EXPORT_TO_GDP_NULL_SUMMARY_V1.json').write_text(json.dumps(summ,ensure_ascii=False,indent=2)+'\n'); status='supported_predictive' if summ['minimum_coverage_pass'] and p is not None and p<.05 and observed>0 and (val is None or val>0) else ('not_testable' if not summ['minimum_coverage_pass'] else 'rejected'); selected_h=int(cm.loc[cm.risk_diff.idxmax(),'horizon']) if cm.risk_diff.notna().any() else None; ev={'transition_id':'IMF_IMTS_EXPORT_CONTRACTION_TO_GDP_V1','source_state':'imf_imts_export_world_raw_contraction','target_state':'wdi_material_gdp_deterioration','lag':{'value':selected_h,'unit':'years','direction':'forward'} if selected_h else {'value':None,'unit':'years','direction':'not_testable'},'split':'confirmation_2019_2021','metric':{'name':'risk_difference','value':observed,'validation_at_selected_horizon':val},'null_method':summ['null_method'],'p_value':p,'entity_holdout':False,'source_refs':['experimental_contracts/IMF_IMTS_EXPORT_CONTRACTION_TO_GDP_CONTRACT_V1.json','experiments/multi_domain_native_edges_v1/imf_imts_v1/IMF_IMTS_OBSERVED_RECORDS_2000_2024.csv','catalog_first/readiness_gate/macro_plus_eia_energy/MACRO_PLUS_EIA_ENERGY_COMPLETE_139_NUMERIC_RAW_2000_2024_WIDE.csv','experiments/multi_domain_native_edges_v1/imf_imts_export_to_gdp_v1/IMF_IMTS_EXPORT_TO_GDP_METRICS_V1.csv','experiments/multi_domain_native_edges_v1/imf_imts_export_to_gdp_v1/IMF_IMTS_EXPORT_TO_GDP_NULL_SUMMARY_V1.json'],'edge_status':status,'causal_claim':False,'failure_cases':['no entity holdout','confirmation origins only 2019-2021','target outcome uses future GDP by design of transition test','raw export value only; no normalization','bounded 15-reporter extract','no source reconciliation']}; (OUT/'IMF_IMTS_EXPORT_TO_GDP_TRANSITION_EVIDENCE_V1.jsonl').write_text(json.dumps(ev,ensure_ascii=False,sort_keys=True)+'\n'); print(json.dumps({'status':status,'observed':observed,'p_value':p,'min_coverage':summ['minimum_coverage_pass'],'metrics':metrics},ensure_ascii=False,indent=2))
if __name__=='__main__': main()
